=== FILE: apb_gpio.v ===
`timescale 1ns / 1ps
`default_nettype none

// apb_gpio: APB4 GPIO with edge/level interrupt detection.
// Implements interface_spec.md and microarchitecture.md (prj-b3c686270a).
module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0..N-1 set: the pins that exist.
    localparam [31:0] PINS = {32{1'b1}} >> (32 - N);

    localparam [3:0] IDX_DOUT = 4'd0;
    localparam [3:0] IDX_DIR  = 4'd1;
    localparam [3:0] IDX_DIN  = 4'd2;
    localparam [3:0] IDX_RISE = 4'd3;
    localparam [3:0] IDX_FALL = 4'd4;
    localparam [3:0] IDX_HIGH = 4'd5;
    localparam [3:0] IDX_LOW  = 4'd6;
    localparam [3:0] IDX_EN   = 4'd7;
    localparam [3:0] IDX_STAT = 4'd8;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg [31:0] data_out;
    reg [31:0] dir;
    reg [31:0] intr_rise;
    reg [31:0] intr_fall;
    reg [31:0] intr_high;
    reg [31:0] intr_low;
    reg [31:0] intr_en;
    reg [31:0] status;
    reg [31:0] in_q;
    reg [31:0] in_prev;

    // ------------------------------------------------------------------
    // APB decode: zero wait states, completion = psel & penable
    // ------------------------------------------------------------------
    wire       access   = psel & penable;
    wire [3:0] idx      = paddr[5:2];
    wire       aligned  = (paddr[1:0] == 2'b00);
    wire       high_clr = ((paddr >> 6) == {ADDR_WIDTH{1'b0}});
    wire       mapped   = aligned & high_clr & (idx <= IDX_STAT);
    wire       wr_acc   = access & pwrite & mapped;
    wire       rd_acc   = access & ~pwrite & mapped;

    assign pready  = 1'b1;
    assign pslverr = access & (~mapped | (pwrite & (idx == IDX_DIN)));

    wire we_dout = wr_acc & (idx == IDX_DOUT);
    wire we_dir  = wr_acc & (idx == IDX_DIR);
    wire we_rise = wr_acc & (idx == IDX_RISE);
    wire we_fall = wr_acc & (idx == IDX_FALL);
    wire we_high = wr_acc & (idx == IDX_HIGH);
    wire we_low  = wr_acc & (idx == IDX_LOW);
    wire we_en   = wr_acc & (idx == IDX_EN);
    wire we_stat = wr_acc & (idx == IDX_STAT);

    // Byte strobes expanded to bits, restricted to existing pins.
    wire [31:0] strb_mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}};
    wire [31:0] wmask     = strb_mask & PINS;
    wire [31:0] wbits     = pwdata & wmask;

    wire [31:0] data_out_d  = we_dout ? ((data_out  & ~wmask) | wbits) : data_out;
    wire [31:0] dir_d       = we_dir  ? ((dir       & ~wmask) | wbits) : dir;
    wire [31:0] intr_rise_d = we_rise ? ((intr_rise & ~wmask) | wbits) : intr_rise;
    wire [31:0] intr_fall_d = we_fall ? ((intr_fall & ~wmask) | wbits) : intr_fall;
    wire [31:0] intr_high_d = we_high ? ((intr_high & ~wmask) | wbits) : intr_high;
    wire [31:0] intr_low_d  = we_low  ? ((intr_low  & ~wmask) | wbits) : intr_low;
    wire [31:0] intr_en_d   = we_en   ? ((intr_en   & ~wmask) | wbits) : intr_en;

    // ------------------------------------------------------------------
    // Input widening (zeros above N)
    // ------------------------------------------------------------------
    wire [31:0] gpio_in_w;
    generate
        if (N < 32) begin : g_in_pad
            assign gpio_in_w = {{(32 - N){1'b0}}, gpio_in};
        end else begin : g_in_full
            assign gpio_in_w = gpio_in;
        end
    endgenerate

    // ------------------------------------------------------------------
    // Detection and status (detection beats clear)
    // ------------------------------------------------------------------
    wire [31:0] rise     = in_q & ~in_prev;
    wire [31:0] fall     = ~in_q & in_prev;
    wire [31:0] detected = ((rise & intr_rise) | (fall & intr_fall)
                          | (in_q & intr_high) | (~in_q & intr_low)) & PINS;
    wire [31:0] clr      = we_stat ? wbits : 32'd0;
    wire [31:0] status_d = (status & ~clr) | detected;

    // ------------------------------------------------------------------
    // Register block: synchronous active-low reset
    // ------------------------------------------------------------------
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out  <= 32'd0;
            dir       <= 32'd0;
            intr_rise <= 32'd0;
            intr_fall <= 32'd0;
            intr_high <= 32'd0;
            intr_low  <= 32'd0;
            intr_en   <= 32'd0;
            status    <= 32'd0;
            in_q      <= 32'd0;
            in_prev   <= 32'd0;
        end else begin
            data_out  <= data_out_d;
            dir       <= dir_d;
            intr_rise <= intr_rise_d;
            intr_fall <= intr_fall_d;
            intr_high <= intr_high_d;
            intr_low  <= intr_low_d;
            intr_en   <= intr_en_d;
            status    <= status_d;
            in_q      <= gpio_in_w;
            in_prev   <= in_q;
        end
    end

    // ------------------------------------------------------------------
    // Read multiplexer: zero unless a mapped read access
    // ------------------------------------------------------------------
    reg [31:0] rdata;
    always @(*) begin
        rdata = 32'd0;
        if (rd_acc) begin
            case (idx)
                IDX_DOUT: rdata = data_out;
                IDX_DIR:  rdata = dir;
                IDX_DIN:  rdata = in_q;
                IDX_RISE: rdata = intr_rise;
                IDX_FALL: rdata = intr_fall;
                IDX_HIGH: rdata = intr_high;
                IDX_LOW:  rdata = intr_low;
                IDX_EN:   rdata = intr_en;
                IDX_STAT: rdata = status;
                default:  rdata = 32'd0;
            endcase
        end
    end

    assign prdata   = rdata;
    assign gpio_out = data_out[N-1:0];
    assign gpio_oe  = dir[N-1:0];
    assign irq      = |(status & intr_en);

`ifdef FORMAL
    // Design-intent assertions (not a full proof; see notes).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    always @(*) begin
        assert (pready == 1'b1);
        if (!access) begin
            assert (pslverr == 1'b0);
            assert (prdata == 32'd0);
        end
        assert (irq == |(status & intr_en));
    end

    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert (data_out  == 32'd0);
            assert (dir       == 32'd0);
            assert (intr_rise == 32'd0);
            assert (intr_fall == 32'd0);
            assert (intr_high == 32'd0);
            assert (intr_low  == 32'd0);
            assert (intr_en   == 32'd0);
            assert (status    == 32'd0);
            assert (in_q      == 32'd0);
            assert (in_prev   == 32'd0);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns / 1ps

// Self-checking testbench for apb_gpio (interface_spec.md section 8).
// Two instances, N=8 and N=32, share one APB bus and one 32-bit pin vector;
// every per-pin behaviour is bitwise, so the N=8 expectation is the N=32
// expectation masked to bits 7:0.
module apb_gpio_tb;

    reg         clk = 1'b0;
    reg         rstn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gin;

    wire [31:0] prdata_a;
    wire        pready_a;
    wire        pslverr_a;
    wire [7:0]  gout_a;
    wire [7:0]  goe_a;
    wire        irq_a;

    wire [31:0] prdata_b;
    wire        pready_b;
    wire        pslverr_b;
    wire [31:0] gout_b;
    wire [31:0] goe_b;
    wire        irq_b;

    integer passed      = 0;
    integer failed      = 0;
    integer idle_passed = 0;
    integer idle_failed = 0;
    reg     checks_on;
    reg [8*64-1:0] nonce;

    localparam [7:0] A_DOUT = 8'h00;
    localparam [7:0] A_DIR  = 8'h04;
    localparam [7:0] A_DIN  = 8'h08;
    localparam [7:0] A_RISE = 8'h0C;
    localparam [7:0] A_FALL = 8'h10;
    localparam [7:0] A_HIGH = 8'h14;
    localparam [7:0] A_LOW  = 8'h18;
    localparam [7:0] A_EN   = 8'h1C;
    localparam [7:0] A_STAT = 8'h20;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut_a (
        .pclk(clk), .presetn(rstn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata_a), .pready(pready_a), .pslverr(pslverr_a),
        .gpio_in(gin[7:0]), .gpio_out(gout_a), .gpio_oe(goe_a), .irq(irq_a)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut_b (
        .pclk(clk), .presetn(rstn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata_b), .pready(pready_b), .pslverr(pslverr_b),
        .gpio_in(gin), .gpio_out(gout_b), .gpio_oe(goe_b), .irq(irq_b)
    );

    always #5 clk = ~clk;

    // Outside the access phase prdata and pslverr must be zero; the two
    // instances must agree on the pins they share.
    always @(negedge clk) begin
        if (checks_on) begin
            if (!(psel && penable)) begin
                if (prdata_a === 32'd0 && prdata_b === 32'd0 &&
                    pslverr_a === 1'b0 && pslverr_b === 1'b0)
                    idle_passed = idle_passed + 1;
                else begin
                    idle_failed = idle_failed + 1;
                    $error("outside access: prdata a=%08h b=%08h pslverr a=%b b=%b",
                           prdata_a, prdata_b, pslverr_a, pslverr_b);
                end
            end
            if (gout_a === gout_b[7:0] && goe_a === goe_b[7:0])
                idle_passed = idle_passed + 1;
            else begin
                idle_failed = idle_failed + 1;
                $error("lane mismatch: gout a=%02h b=%08h goe a=%02h b=%08h",
                       gout_a, gout_b, goe_a, goe_b);
            end
        end
    end

    task tick;
        begin
            @(posedge clk);
            #1;
        end
    endtask

    task apb_wr;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        input        exp_err;
        begin
            paddr   = addr;
            pwrite  = 1'b1;
            pwdata  = data;
            pstrb   = strb;
            psel    = 1'b1;
            penable = 1'b0;
            @(posedge clk);
            #1;
            penable = 1'b1;
            #1;
            if (pready_a === 1'b1 && pready_b === 1'b1)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("write 0x%02h: pready a=%b b=%b in access", addr, pready_a, pready_b);
            end
            if (pslverr_a === exp_err && pslverr_b === exp_err)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("write 0x%02h: pslverr a=%b b=%b, expected %b",
                       addr, pslverr_a, pslverr_b, exp_err);
            end
            @(posedge clk);
            #1;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'd0;
        end
    endtask

    task apb_rd;
        input [7:0]  addr;
        input [31:0] expv;
        input        exp_err;
        reg   [31:0] exp_a;
        begin
            exp_a   = expv & 32'h0000_00FF;
            paddr   = addr;
            pwrite  = 1'b0;
            pwdata  = 32'd0;
            pstrb   = 4'd0;
            psel    = 1'b1;
            penable = 1'b0;
            @(posedge clk);
            #1;
            penable = 1'b1;
            #1;
            if (pready_a === 1'b1 && pready_b === 1'b1)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("read 0x%02h: pready a=%b b=%b in access", addr, pready_a, pready_b);
            end
            if (prdata_a === exp_a && prdata_b === expv)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("read 0x%02h: prdata a=%08h b=%08h, expected a=%08h b=%08h",
                       addr, prdata_a, prdata_b, exp_a, expv);
            end
            if (pslverr_a === exp_err && pslverr_b === exp_err)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("read 0x%02h: pslverr a=%b b=%b, expected %b",
                       addr, pslverr_a, pslverr_b, exp_err);
            end
            @(posedge clk);
            #1;
            psel    = 1'b0;
            penable = 1'b0;
        end
    endtask

    task chk_irq;
        input ea;
        input eb;
        input integer tag;
        begin
            if (irq_a === ea && irq_b === eb)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("[%0d] irq a=%b b=%b, expected a=%b b=%b", tag, irq_a, irq_b, ea, eb);
            end
        end
    endtask

    task chk_pins;
        input [31:0] eo;
        input [31:0] ee;
        input integer tag;
        begin
            if (gout_a === eo[7:0] && gout_b === eo && goe_a === ee[7:0] && goe_b === ee)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("[%0d] gout a=%02h b=%08h goe a=%02h b=%08h, expected out=%08h oe=%08h",
                       tag, gout_a, gout_b, goe_a, goe_b, eo, ee);
            end
        end
    endtask

    // Watchdog
    initial begin
        #200000;
        $error("timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                 passed + idle_passed, failed + idle_failed + 1);
        $finish;
    end

    initial begin
        checks_on = 1'b0;
        rstn      = 1'b0;
        paddr     = 8'd0;
        psel      = 1'b0;
        penable   = 1'b0;
        pwrite    = 1'b0;
        pwdata    = 32'd0;
        pstrb     = 4'd0;
        gin       = 32'd0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {512{1'b0}};

        // ---------------- Reset ----------------
        tick; tick; tick;
        checks_on = 1'b1;
        chk_pins(32'd0, 32'd0, 1);
        chk_irq(1'b0, 1'b0, 2);
        rstn = 1'b1;
        tick;

        // Reset values of every register
        apb_rd(A_DOUT, 32'd0, 1'b0);
        apb_rd(A_DIR,  32'd0, 1'b0);
        apb_rd(A_DIN,  32'd0, 1'b0);
        apb_rd(A_RISE, 32'd0, 1'b0);
        apb_rd(A_FALL, 32'd0, 1'b0);
        apb_rd(A_HIGH, 32'd0, 1'b0);
        apb_rd(A_LOW,  32'd0, 1'b0);
        apb_rd(A_EN,   32'd0, 1'b0);
        apb_rd(A_STAT, 32'd0, 1'b0);

        // ---------------- DATA_OUT / DIR, full and partial strobes ----------------
        apb_wr(A_DOUT, 32'hA5C3_5A3C, 4'hF, 1'b0);
        apb_rd(A_DOUT, 32'hA5C3_5A3C, 1'b0);
        chk_pins(32'hA5C3_5A3C, 32'h0000_0000, 10);
        apb_wr(A_DIR, 32'h0F0F_F0F0, 4'hF, 1'b0);
        apb_rd(A_DIR, 32'h0F0F_F0F0, 1'b0);
        chk_pins(32'hA5C3_5A3C, 32'h0F0F_F0F0, 11);
        apb_wr(A_DOUT, 32'hFFFF_FFFF, 4'b0101, 1'b0);
        apb_rd(A_DOUT, 32'hA5FF_5AFF, 1'b0);
        apb_wr(A_DOUT, 32'h0000_0000, 4'b1000, 1'b0);
        apb_rd(A_DOUT, 32'h00FF_5AFF, 1'b0);
        apb_wr(A_DOUT, 32'h1234_5678, 4'b0000, 1'b0);
        apb_rd(A_DOUT, 32'h00FF_5AFF, 1'b0);
        apb_wr(A_DOUT, 32'h0000_0000, 4'b0001, 1'b0);
        apb_rd(A_DOUT, 32'h00FF_5A00, 1'b0);
        chk_pins(32'h00FF_5A00, 32'h0F0F_F0F0, 12);
        apb_wr(A_DIR, 32'h1234_5678, 4'b0110, 1'b0);
        apb_rd(A_DIR, 32'h0F34_56F0, 1'b0);
        chk_pins(32'h00FF_5A00, 32'h0F34_56F0, 13);

        // ---------------- Detection enables (pins stay 0) ----------------
        apb_wr(A_RISE, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_RISE, 32'hFFFF_FFFF, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'b0011, 1'b0);
        apb_rd(A_RISE, 32'hFFFF_0000, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_RISE, 32'h0000_0000, 1'b0);
        apb_wr(A_FALL, 32'hDEAD_BEEF, 4'hF, 1'b0);
        apb_rd(A_FALL, 32'hDEAD_BEEF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'b1100, 1'b0);
        apb_rd(A_FALL, 32'h0000_BEEF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_FALL, 32'h0000_0000, 1'b0);
        apb_wr(A_HIGH, 32'hCAFE_F00D, 4'hF, 1'b0);
        apb_rd(A_HIGH, 32'hCAFE_F00D, 1'b0);
        apb_wr(A_HIGH, 32'hFFFF_FFFF, 4'b0010, 1'b0);
        apb_rd(A_HIGH, 32'hCAFE_FF0D, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_HIGH, 32'h0000_0000, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // Low level on bits 0 and 31 (31 exists only at N=32)
        apb_wr(A_LOW, 32'h8000_0001, 4'hF, 1'b0);
        apb_rd(A_LOW, 32'h8000_0001, 1'b0);
        apb_rd(A_STAT, 32'h8000_0001, 1'b0);
        chk_irq(1'b0, 1'b0, 14);
        apb_wr(A_EN, 32'h8000_0000, 4'hF, 1'b0);
        apb_rd(A_EN, 32'h8000_0000, 1'b0);
        chk_irq(1'b0, 1'b1, 15);
        apb_wr(A_EN, 32'h0000_0001, 4'b0001, 1'b0);
        apb_rd(A_EN, 32'h8000_0001, 1'b0);
        chk_irq(1'b1, 1'b1, 16);
        apb_wr(A_LOW, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h8000_0001, 1'b0);
        apb_wr(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h8000_0000, 1'b0);
        chk_irq(1'b0, 1'b1, 17);
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'b0111, 1'b0);
        apb_rd(A_STAT, 32'h8000_0000, 1'b0);
        apb_wr(A_STAT, 32'h8000_0000, 4'b1000, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_irq(1'b0, 1'b0, 18);
        apb_wr(A_EN, 32'h0000_0000, 4'hF, 1'b0);
        apb_rd(A_EN, 32'h0000_0000, 1'b0);

        // DATA_IN is read only
        apb_wr(A_DIN, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_rd(A_DIN, 32'h0000_0000, 1'b0);
        apb_rd(A_DOUT, 32'h00FF_5A00, 1'b0);

        // ---------------- PSLVERR policy: unmapped addresses ----------------
        apb_wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h28, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h21, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h4C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h60, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_wr(8'hA0, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_rd(A_DOUT, 32'h00FF_5A00, 1'b0);
        apb_rd(A_DIR,  32'h0F34_56F0, 1'b0);
        apb_rd(A_RISE, 32'h0000_0000, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_pins(32'h00FF_5A00, 32'h0F34_56F0, 20);
        apb_rd(8'h24, 32'h0000_0000, 1'b1);
        apb_rd(8'h40, 32'h0000_0000, 1'b1);
        apb_rd(8'h41, 32'h0000_0000, 1'b1);
        apb_rd(8'h44, 32'h0000_0000, 1'b1);
        apb_rd(8'h06, 32'h0000_0000, 1'b1);
        apb_rd(8'h23, 32'h0000_0000, 1'b1);
        apb_rd(8'h60, 32'h0000_0000, 1'b1);
        apb_rd(8'h81, 32'h0000_0000, 1'b1);
        apb_rd(8'hFC, 32'h0000_0000, 1'b1);

        // ---------------- DATA_IN sampling ----------------
        gin = 32'h8000_00A5;
        apb_rd(A_DIN, 32'h8000_00A5, 1'b0);
        gin = 32'h0000_0000;
        apb_rd(A_DIN, 32'h0000_0000, 1'b0);
        tick;

        // ---------------- Rising edge: fires once, timing ----------------
        apb_wr(A_RISE, 32'h0000_0102, 4'hF, 1'b0);
        apb_wr(A_EN,   32'h0000_0102, 4'hF, 1'b0);
        gin = 32'h0000_0102;
        chk_irq(1'b0, 1'b0, 30);
        tick;                       // edge E: sampled
        chk_irq(1'b0, 1'b0, 31);
        tick;                       // edge E+1: status set
        chk_irq(1'b1, 1'b1, 32);
        apb_rd(A_STAT, 32'h0000_0102, 1'b0);
        apb_wr(A_STAT, 32'h0000_0102, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        tick; tick;
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_irq(1'b0, 1'b0, 33);

        // ---------------- Falling edge, partial W1C ----------------
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0102, 4'hF, 1'b0);
        gin = 32'h0000_0000;
        chk_irq(1'b0, 1'b0, 34);
        tick;
        chk_irq(1'b0, 1'b0, 35);
        tick;
        chk_irq(1'b1, 1'b1, 36);
        apb_rd(A_STAT, 32'h0000_0102, 1'b0);
        apb_wr(A_STAT, 32'h0000_0002, 4'b0001, 1'b0);
        apb_rd(A_STAT, 32'h0000_0100, 1'b0);
        chk_irq(1'b0, 1'b1, 37);
        apb_wr(A_STAT, 32'h0000_0100, 4'b0010, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_irq(1'b0, 1'b0, 38);

        // ---------------- One-cycle pulse, both edges, masked ----------------
        apb_wr(A_RISE, 32'h0000_0001, 4'hF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0001, 4'hF, 1'b0);
        gin = 32'h0000_0001;
        tick;
        gin = 32'h0000_0000;
        tick; tick; tick;
        apb_rd(A_STAT, 32'h0000_0001, 1'b0);
        chk_irq(1'b0, 1'b0, 40);
        apb_wr(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        apb_wr(A_FALL, 32'h0000_0000, 4'hF, 1'b0);

        // ---------------- High level: a clear does not stick ----------------
        apb_wr(A_EN,   32'h0000_0004, 4'hF, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0004, 4'hF, 1'b0);
        gin = 32'h0000_0004;
        chk_irq(1'b0, 1'b0, 50);
        tick;
        chk_irq(1'b0, 1'b0, 51);
        tick;
        chk_irq(1'b1, 1'b1, 52);
        apb_wr(A_STAT, 32'h0000_0004, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0004, 1'b0);
        chk_irq(1'b1, 1'b1, 53);
        tick;
        apb_rd(A_STAT, 32'h0000_0004, 1'b0);
        gin = 32'h0000_0000;
        apb_wr(A_STAT, 32'h0000_0004, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_irq(1'b0, 1'b0, 54);
        apb_wr(A_HIGH, 32'h0000_0000, 4'hF, 1'b0);

        // ---------------- Low level, interrupt mask ----------------
        apb_wr(A_LOW, 32'h0000_0008, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0008, 1'b0);
        chk_irq(1'b0, 1'b0, 60);
        apb_wr(A_EN, 32'h0000_000C, 4'hF, 1'b0);
        chk_irq(1'b1, 1'b1, 61);
        apb_wr(A_EN, 32'h0000_0004, 4'hF, 1'b0);
        chk_irq(1'b0, 1'b0, 62);
        apb_rd(A_STAT, 32'h0000_0008, 1'b0);
        gin = 32'h0000_0008;
        apb_wr(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        apb_wr(A_LOW, 32'h0000_0000, 4'hF, 1'b0);
        gin = 32'h0000_0000;
        apb_wr(A_EN, 32'h0000_0000, 4'hF, 1'b0);
        tick; tick;
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---------------- Detection beats a clear on the same edge ----------------
        apb_wr(A_RISE, 32'h0000_0011, 4'hF, 1'b0);
        gin = 32'h0000_0011;
        tick; tick;
        apb_rd(A_STAT, 32'h0000_0011, 1'b0);
        gin = 32'h0000_0001;
        tick; tick;
        apb_rd(A_STAT, 32'h0000_0011, 1'b0);
        gin = 32'h0000_0011;        // new rise on bit 4, detected on the clear edge
        apb_wr(A_STAT, 32'h0000_0011, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0010, 1'b0);
        apb_rd(A_STAT, 32'h0000_0010, 1'b0);
        apb_wr(A_STAT, 32'h0000_0010, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        apb_wr(A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        gin = 32'h0000_0000;
        tick; tick;
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);

        // ---------------- Upper pins (N=32 lane only) ----------------
        apb_wr(A_HIGH, 32'h8010_0000, 4'hF, 1'b0);
        apb_wr(A_EN,   32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_EN,   32'hFFFF_FFFF, 1'b0);
        gin = 32'h8010_0000;
        chk_irq(1'b0, 1'b0, 70);
        tick;
        chk_irq(1'b0, 1'b0, 71);
        tick;
        chk_irq(1'b0, 1'b1, 72);
        apb_rd(A_STAT, 32'h8010_0000, 1'b0);
        apb_rd(A_DIN,  32'h8010_0000, 1'b0);
        apb_wr(A_HIGH, 32'h0000_0000, 4'hF, 1'b0);
        gin = 32'h0000_0000;
        apb_wr(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_irq(1'b0, 1'b0, 73);

        // ---------------- Reset again, with state set ----------------
        apb_wr(A_DOUT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_wr(A_DIR,  32'hFFFF_FFFF, 4'hF, 1'b0);
        apb_wr(A_HIGH, 32'hFFFF_FFFF, 4'hF, 1'b0);
        gin = 32'hFFFF_FFFF;
        tick; tick;
        chk_irq(1'b1, 1'b1, 80);
        chk_pins(32'hFFFF_FFFF, 32'hFFFF_FFFF, 81);
        rstn = 1'b0;
        tick;
        chk_pins(32'd0, 32'd0, 82);
        chk_irq(1'b0, 1'b0, 83);
        tick;
        rstn = 1'b1;
        tick;
        apb_rd(A_DOUT, 32'h0000_0000, 1'b0);
        apb_rd(A_DIR,  32'h0000_0000, 1'b0);
        apb_rd(A_DIN,  32'hFFFF_FFFF, 1'b0);
        apb_rd(A_RISE, 32'h0000_0000, 1'b0);
        apb_rd(A_FALL, 32'h0000_0000, 1'b0);
        apb_rd(A_HIGH, 32'h0000_0000, 1'b0);
        apb_rd(A_LOW,  32'h0000_0000, 1'b0);
        apb_rd(A_EN,   32'h0000_0000, 1'b0);
        apb_rd(A_STAT, 32'h0000_0000, 1'b0);
        chk_irq(1'b0, 1'b0, 84);
        chk_pins(32'd0, 32'd0, 85);

        tick; tick;
        checks_on = 1'b0;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
                 passed + idle_passed, failed + idle_failed);
        $finish;
    end

endmodule
